/**
 * Fixed-timestep game loop with render interpolation.
 *
 * - Simulation advances in fixed `dt` increments via an accumulator.
 * - Incoming frame times are clamped to 250 ms to avoid the "spiral of death"
 *   (a slow frame demanding more catch-up ticks, which makes the next frame
 *   slower still).
 * - After advancing, the loop reports `alpha = accumulator / dt`, the fractional
 *   progress between the previous and current tick, so the renderer can
 *   interpolate visual state: `rendered = lerp(prevState, currState, alpha)`.
 */

/** Maximum simulated time (in seconds) accepted from a single frame. */
export const MAX_FRAME_TIME_SECONDS = 0.25;

export interface FixedLoopOptions {
  /** Fixed simulation step in seconds (must be > 0 and finite). */
  dt: number;
  /** Advance the simulation by exactly one fixed step of `dt`. */
  update: (dt: number) => void;
  /** Called once per frame with alpha = accumulator / dt ∈ [0, 1). */
  render?: (alpha: number) => void;
}

export interface FixedLoop {
  readonly dt: number;
  /** Number of update ticks that have run so far. */
  readonly ticks: number;
  /** Total real time fed into the loop (after clamping), in seconds. */
  readonly clampedFrameTime: number;
  /** Current interpolation factor: accumulator / dt, in [0, 1). */
  readonly alpha: number;
  /**
   * Feed one observed frame of `frameTimeSeconds`. The time is clamped to
   * {@link MAX_FRAME_TIME_SECONDS}, then drained by the accumulator in fixed
   * `dt` steps before a single render callback fires.
   */
  advance(frameTimeSeconds: number): void;
}

export function createFixedLoop(options: FixedLoopOptions): FixedLoop {
  const { dt, update, render } = options;
  if (!Number.isFinite(dt) || dt <= 0) {
    throw new RangeError(`dt must be a positive finite number, got ${dt}`);
  }

  let accumulator = 0;
  let ticks = 0;
  let clampedFrameTime = 0;

  return {
    dt,
    get ticks() {
      return ticks;
    },
    get clampedFrameTime() {
      return clampedFrameTime;
    },
    get alpha() {
      return accumulator / dt;
    },
    advance(frameTimeSeconds: number): void {
      const frame = Math.min(Math.max(frameTimeSeconds, 0), MAX_FRAME_TIME_SECONDS);
      clampedFrameTime += frame;
      accumulator += frame;

      while (accumulator >= dt) {
        update(dt);
        ticks += 1;
        accumulator -= dt;
      }

      render?.(accumulator / dt);
    },
  };
}

/**
 * Linear interpolation between two scalar states, used for render interpolation:
 * `lerp(prev, curr, alpha)` where `alpha = accumulator / dt`.
 */
export function lerp(prev: number, curr: number, alpha: number): number {
  return prev + (curr - prev) * alpha;
}

export interface DotSim {
  /** Position after the most recent completed tick ("current" state). */
  readonly x: number;
  /** Position before the most recent completed tick ("previous" state). */
  readonly prevX: number;
  readonly ticks: number;
  readonly alpha: number;
  /** Interpolated render position: lerp(prevX, x, alpha). */
  readonly renderedX: number;
  /** Drive the simulation with one frame's elapsed time (seconds). */
  frame(frameTimeSeconds: number): void;
}

/**
 * A dot moving at constant `velocity` (units/second), simulated on a fixed
 * timestep. Keeps the previous tick state so the renderer can interpolate.
 */
export function createDotSim(velocity: number, dt: number): DotSim {
  let prevX = 0;
  let x = 0;
  let alpha = 0;

  const loop = createFixedLoop({
    dt,
    update(step) {
      prevX = x;
      x += velocity * step;
    },
    render(a) {
      alpha = a;
    },
  });

  return {
    get x() {
      return x;
    },
    get prevX() {
      return prevX;
    },
    get ticks() {
      return loop.ticks;
    },
    get alpha() {
      return alpha;
    },
    get renderedX() {
      return lerp(prevX, x, alpha);
    },
    frame(seconds) {
      loop.advance(seconds);
    },
  };
}

