import { describe, expect, it } from "vitest";

import {
  MAX_FRAME_TIME_SECONDS,
  createDotSim,
  createFixedLoop,
  lerp,
} from "./loop.js";

/** Deterministic PRNG (mulberry32) so the "mixed frames" test is repeatable. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

describe("fixed-timestep loop", () => {
  it("interpolated position at alpha=0.5 is exactly midway between previous and current tick states", () => {
    const dt = 0.1;
    const velocity = 3; // units per second
    const sim = createDotSim(velocity, dt);

    // One full tick leaves alpha = 0.
    sim.frame(dt);
    expect(sim.alpha).toBe(0);

    // Half a tick more: accumulator = dt/2, so alpha = 0.5 exactly.
    sim.frame(dt / 2);
    expect(sim.alpha).toBe(0.5);

    // The last tick moved prevX -> x; interpolation at 0.5 must be the midpoint.
    const interpolated = lerp(sim.prevX, sim.x, sim.alpha);
    const midpoint = sim.prevX + (sim.x - sim.prevX) * 0.5;
    expect(interpolated).toBe(midpoint);

    // And that midpoint really is halfway along the step of size v*dt.
    expect(sim.x - sim.prevX).toBeCloseTo(velocity * dt, 12);
    expect(interpolated).toBeGreaterThan(sim.prevX);
    expect(interpolated).toBeLessThan(sim.x);
  });

  it("a pathological 10-second frame advances at most ceil(0.25/dt) ticks", () => {
    const dt = 1 / 60;
    let updates = 0;
    const loop = createFixedLoop({
      dt,
      update: () => {
        updates += 1;
      },
    });

    loop.advance(10); // ten seconds in a single frame!

    const maxTicks = Math.ceil(MAX_FRAME_TIME_SECONDS / dt);
    expect(updates).toBeLessThanOrEqual(maxTicks);
    expect(loop.ticks).toBe(updates);
    // The clamp itself: only 250 ms of the 10 s was ever simulated.
    expect(loop.clampedFrameTime).toBe(MAX_FRAME_TIME_SECONDS);
    // With dt = 1/60 and a 250 ms cap this is exactly floor(0.25/dt) = 15 ticks.
    expect(updates).toBe(Math.floor(MAX_FRAME_TIME_SECONDS / dt));
  });

  it("1000 mixed frames produce a deterministic, repeatable tick count", () => {
    const dt = 1 / 120;

    function runMixedFrames(seed: number): { ticks: number; x: number } {
      const sim = createDotSim(2.5, dt);
      const rand = mulberry32(seed);
      for (let i = 0; i < 1000; i++) {
        // Mixed durations: mostly normal frames, occasional spikes far past
        // the clamp threshold. All are clamped to <= 250 ms internally.
        const r = rand();
        const seconds =
          r < 0.02 ? 0.008 + rand() * 9.99 : 0.002 + rand() * 0.03;
        sim.frame(seconds);
      }
      return { ticks: sim.ticks, x: sim.x };
    }

    const first = runMixedFrames(0xc0ffee);
    const second = runMixedFrames(0xc0ffee);

    expect(second.ticks).toBe(first.ticks);
    expect(second.x).toBe(first.x);

    // Sanity: total simulated time equals sum of clamped frames, so ticks must
    // be bounded by ceil(totalClamped / dt).
    const upperBoundTicks = Math.ceil((1000 * MAX_FRAME_TIME_SECONDS) / dt);
    expect(first.ticks).toBeLessThanOrEqual(upperBoundTicks);
    expect(first.ticks).toBeGreaterThan(1000); // mixed frames did real work
  });
});

